    col *= 1.0 - ribA * 0.35 * smoothstep(0.2, -1.0, ridge);   // the grooves between ribs
    col += vec3(1.0, 0.8, 0.94) * (spec + 1.1 * aniso) * (1.2 + 0.3 * gSilkSwell + 0.4 * gSilkHi);
